CREATE TABLE IF NOT EXISTS correction_resolutions (id INTEGER PRIMARY KEY AUTOINCREMENT, correction_id INTEGER NOT NULL REFERENCES article_corrections(id), article_id INTEGER NOT NULL REFERENCES articles(id), resolution TEXT NOT NULL, note TEXT, previous_status TEXT, new_status TEXT, corrected_text TEXT, verification_verdict TEXT, resolved_by TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_correction_resolutions_correction ON correction_resolutions(correction_id);
